import{REST as s}from"../../shared/js/avatar-figure-1.0.0.min.js";export const MAX_HEAD_TURN=1.1,ARM_POSES=Object.freeze({stand:null,dismiss:Object.freeze({z:.4,x:-1.1,fore:-1.1,twist:Math.PI}),approve:Object.freeze({z:.3,x:-1.9,fore:-.4,twist:0}),present:Object.freeze({z:1.25,x:-.5,fore:-.6,twist:0}),shake:Object.freeze({z:.1,x:-1,fore:-.7,twist:0}),lookBack:null}),HANDSHAKE=Object.freeze({gap:.8,aside:.23,turn:.5}),HEAD_TURNS=Object.freeze({stand:0,dismiss:.45,approve:0,present:.25,shake:0,lookBack:.95}),POSES=Object.freeze(Object.keys(ARM_POSES));export function armsFor(r,o="right"){const e=ARM_POSES[r],t={...s};return e?(o==="left"?"left":"right")==="right"?{right:{...e},left:t}:{right:t,left:{...e}}:{right:{...t},left:{...t}}}export function headTurnFor(r,o="right"){const e=Math.min(MAX_HEAD_TURN,Math.max(0,HEAD_TURNS[r]||0));return e===0?0:o==="left"?e:-e}
